function getMatchingPartDetails(categories) {
  const matchingPartDetails = [];

  const normalize = s => String(s || '').trim().toLowerCase();

  for (const category of categories) {
    const subcategories = category?.SubCategories || [];
    for (const subcategory of subcategories) {
      const parts = subcategory?.Parts || [];

      for (const part of parts) {
        const partDescription = normalize(part?.Description);

        // Skip parts that mention R&I (case-insensitive)
        if (partDescription.includes('r&i')) continue;

        const partDetails = part?.PartDetails || [];

        for (const detail of partDetails) {
          const partObj = detail?.Part || {};
          const priceObj = partObj?.Price || {};
          const currentPrice = priceObj?.CurrentPrice;
          const availableOperations = Array.isArray(detail?.AvailableOperations)
            ? detail.AvailableOperations
            : [];

          // normalize ops and check for keywords robustly
          const opsNormalized = availableOperations.map(o => normalize(o));
          const hasBlend = opsNormalized.some(op => op.includes('blend'));
          const hasRefinish = opsNormalized.some(op => op.includes('refinish'));

          // keep if blend OR refinish (regardless of price)
          if (hasBlend || hasRefinish) {
            const newEntry = {
              ID: detail.Id,
              "Part Detail": detail.FullDescription,
              Category: category.Description,
              SubCategory: subcategory.Description,
              CurrentPrice: currentPrice,
              AvailableOperations: availableOperations
            };

            matchingPartDetails.push(newEntry);
          }
        }
      }
    }
  }
  return matchingPartDetails;
}

const matchingPartDetails = getMatchingPartDetails(blendableAdjacentCategories);

return {
  belndableCategories,
  matchingPartDetails
}

