const ai = $('Open AI Get Blendable Parts').first().json.choices[0].message.content;
const opLinesJson = $('Filter Items').first().json;
const blendableParts =JSON.parse(ai)?.blendableParts || {};

function mergeOpLines(blendableParts, opLinesJson) {
  const op_lines = { ...opLinesJson.op_lines };

  blendableParts.forEach(part => {
    const category = part.Category;
    if (part.ID) {
        part.dbref = part.ID;
      }

    // If category already exists, push into its Lines
    if (op_lines[category]) {
      op_lines[category].Lines.push(part);
    } else {
      // Otherwise, create new category with Lines array
      op_lines[category] = { Lines: [part] };
    }
  });

  // Recalculate total_lines
  let total_lines = 0;
  Object.values(op_lines).forEach(cat => {
    total_lines += cat.Lines.length;
  });
  return {
    op_lines,
    total_lines
  }
}
const output = mergeOpLines(blendableParts,opLinesJson)

return {
  blendableParts,
  op_lines:output.op_lines,
  total_lines:output.total_lines

}

